// COMM-05, UX-11: the export and import page as a person meets it. WRITTEN AND NOT YET RUN: it needs the stack,
// and every M6 slice merged. Keys here are generated by the test, and go nowhere else.
import { generateKeyPairSync } from 'node:crypto';
import type { Page } from '@playwright/test';
import { createOrganization, join, signUp, submit } from '../../helpers/forms';
import { expect, test } from '../support/fixtures';
import { axeFindings, openPanels, sidewaysOverflow, THEMES, WIDTHS } from '../support/look';
import { alertIn } from '../support/notices';
import { makeAdmin } from '../support/people';

const dataPage = (organization: string) => `/o/${organization}/data`;

/** The pair the recipient-key tool would make, with only the shape that matters here. */
function aKeyPair() {
  const { publicKey, privateKey } = generateKeyPairSync('x25519');
  return {
    publicKey: publicKey.export({ type: 'spki', format: 'der' }).toString('base64'),
    privatePem: privateKey.export({ type: 'pkcs8', format: 'pem' }).toString(),
  };
}

async function expectNoProblems(page: Page) {
  const problems: Record<string, unknown> = {};
  const scan = async (label: string) => {
    const findings = await axeFindings(page);
    if (findings.length) problems[label] = findings;
    const overflow = await sidewaysOverflow(page);
    if (overflow > 0) problems[`${label} overflow`] = `${overflow}px sideways`;
  };
  for (const theme of THEMES) {
    await page.emulateMedia({ colorScheme: theme, reducedMotion: 'reduce' });
    for (const width of WIDTHS) {
      await page.setViewportSize({ width, height: width === 375 ? 812 : 800 });
      await scan(`${theme}-${width}`);
      if ((await openPanels(page)) > 0) {
        await scan(`${theme}-${width}-open`);
        await page.evaluate(() => {
          for (const panel of document.querySelectorAll('details[open]')) {
            panel.removeAttribute('open');
          }
        });
      }
    }
  }
  expect(problems).toEqual({});
}

async function tabTo(page: Page, wanted: RegExp, limit = 80) {
  for (let i = 0; i < limit; i += 1) {
    await page.keyboard.press('Tab');
    const stop = await page.evaluate(() => {
      const element = document.activeElement as HTMLElement | null;
      if (!element || element === document.body) return null;
      const style = getComputedStyle(element);
      return {
        name: (
          element.getAttribute('aria-label') ||
          element.closest('label')?.textContent ||
          element.textContent ||
          ''
        ).trim(),
        visible: element.matches(':focus-visible') && style.outlineStyle !== 'none',
      };
    });
    if (!stop) continue;
    expect(stop.visible, `"${stop.name}" shows that it has focus`).toBe(true);
    if (wanted.test(stop.name)) return;
  }
  throw new Error(`Tab never reached ${wanted}`);
}

test.describe('who can reach it', () => {
  test('an owner can inspect the definitions explanation without JavaScript', async ({
    open,
    world,
  }) => {
    const page = await open(world.alice, { javaScriptEnabled: false });
    const response = await page.goto(`${dataPage(world.organization)}/definitions`);
    expect(response?.status()).toBe(200);
    await expect(
      page.getByRole('heading', { name: 'Imported definitions', exact: true }),
    ).toBeVisible();
    await expect(page.getByText('These records need review', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: /activate|verify|approve/i })).toHaveCount(0);
    await expectNoProblems(page);
  });
  test('a member or outsider cannot inspect imported definitions', async ({ open, world }) => {
    for (const person of [world.bob, world.quiet]) {
      const page = await open(person);
      expect((await page.goto(`${dataPage(world.organization)}/definitions`))?.status()).toBe(404);
      await expect(
        page.getByRole('heading', { name: 'Imported definitions', exact: true }),
      ).toHaveCount(0);
    }
  });
  test('a member gets the usual not found, and no link to it', async ({ open, world }) => {
    const page = await open(world.bob);
    const response = await page.goto(dataPage(world.organization));
    expect(response?.status()).toBe(404);
    await expect(page.getByRole('heading', { name: 'Page not found' })).toBeVisible();
    await expect(page.getByRole('link', { name: 'Export and import' })).toHaveCount(0);
  });

  test('an admin is told only an owner can do this, and is offered no form', async ({ open }) => {
    // An organization of its own, so that a new member changes nothing in the shared one.
    const owner = await signUp('Olive Owner');
    const organization = await createOrganization(owner, 'Seen by an admin');
    const admin = await join(owner, organization, 'Ari Admin');
    await makeAdmin(owner, organization, admin);
    const page = await open(admin);
    await page.goto(dataPage(organization));
    await expect(page.getByRole('heading', { name: 'Only an owner can do this' })).toBeVisible();
    await expect(page.getByLabel('Public key')).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'Ask for an export' })).toHaveCount(0);
    await expectNoProblems(page);
  });

  test('someone outside the organization gets what anything missing gets', async ({
    open,
    world,
  }) => {
    const page = await open(world.quiet);
    const response = await page.goto(dataPage(world.organization));
    expect(response?.status()).toBe(404);
  });
});

test.describe('exporting', () => {
  test('asks for a public key, and says where the private one stays', async ({ open, world }) => {
    const page = await open(world.alice);
    await page.goto(dataPage(world.organization));
    await expect(page.getByRole('heading', { name: 'Export and import' })).toBeVisible();
    await expect(page.getByLabel('Public key')).toBeVisible();
    await expect(page.getByText('recipient-key tool')).toBeVisible();
    await expect(page.getByText('The matching private key stays with you')).toBeVisible();
    await expect(page.getByText('Restricted work is left out')).toBeVisible();
    await expect(page.getByLabel(/private key/i)).toHaveCount(0);
    await expectNoProblems(page);
  });

  test('shows an empty state before there are any', async ({ open }) => {
    const person = await signUp('Elsie Empty');
    const organization = await createOrganization(person, 'Empty for now');
    const page = await open(person);
    await page.goto(dataPage(organization));
    await expect(page.getByText('No exports yet.')).toBeVisible();
    await expect(page.getByText('No people have come from an archive yet.')).toBeVisible();
    await expectNoProblems(page);
  });

  test('refuses a pasted private key in words, keeping none of it, without JavaScript', async ({
    open,
    world,
  }) => {
    const { privatePem } = aKeyPair();
    const page = await open(world.alice, { javaScriptEnabled: false });
    await page.goto(dataPage(world.organization));
    // The field is one line, so a browser takes the first line of a paste, which already gives it away.
    await page.getByLabel('Public key').fill(privatePem.split('\n')[0] as string);
    await page.getByRole('button', { name: 'Ask for an export' }).click();
    await expect(alertIn(page)).toContainText('That looks like a private key');
    const body = await page.content();
    expect(body).not.toContain('BEGIN PRIVATE KEY');
    await expect(page.getByLabel('Public key')).toHaveValue('');
  });

  test('refuses something that is not a key', async ({ open, world }) => {
    const page = await open(world.alice);
    await page.goto(dataPage(world.organization));
    await page.getByLabel('Public key').fill('not a key at all');
    await page.getByRole('button', { name: 'Ask for an export' }).click();
    await expect(alertIn(page)).toContainText('Please check the details');
  });

  test('can be asked for with the keyboard alone, and appears with what it left out', async ({
    open,
  }) => {
    const person = await signUp('Kit Keyboard');
    const organization = await createOrganization(person, 'Exported by keyboard');
    const page = await open(person);
    await page.goto(dataPage(organization));
    await tabTo(page, /Public key/);
    await page.keyboard.type(aKeyPair().publicKey);
    await tabTo(page, /Ask for an export/);
    await page.keyboard.press('Enter');
    await expect(page.getByRole('status').filter({ hasText: 'has been asked for' })).toBeVisible();
    await expect(page.getByText('Sealed to key')).toBeVisible();
    // The export's own term, not the sentence above the form that also says what is left out.
    await expect(page.getByRole('term').filter({ hasText: /^Left out$/ })).toBeVisible();
    await expectNoProblems(page);
  });
});

test.describe('importing', () => {
  test('says it takes a new, empty organization, and refuses one that is not', async ({
    open,
    world,
  }) => {
    const page = await open(world.alice);
    await page.goto(dataPage(world.organization));
    await expect(page.getByText('An archive goes into a new, empty organization')).toBeVisible();
    await page.getByText('Take an archive into this organization').click();
    await page.getByLabel(/it cannot take a second/).check();
    await page.getByRole('button', { name: 'Get this organization ready' }).click();
    await expect(alertIn(page)).toContainText('new, empty organization');
  });

  test('gets a new organization ready, and tells the owner what comes next', async ({ open }) => {
    const person = await signUp('Ines Importer');
    const organization = await createOrganization(person, 'Ready for an archive');
    const page = await open(person);
    await page.goto(dataPage(organization));
    await page.getByText('Take an archive into this organization').click();
    await page.getByLabel(/it cannot take a second/).check();
    await page.getByRole('button', { name: 'Get this organization ready' }).click();
    await expect(page.getByText('Waiting for your operator')).toBeVisible();
    await expect(page.getByText('organization-import command')).toBeVisible();
    await expect(page.getByText(organization)).toBeVisible();
    // Asked once. A second one has nothing to press.
    await expect(page.getByRole('button', { name: 'Get this organization ready' })).toHaveCount(0);
    await expectNoProblems(page);
  });

  test('works without JavaScript', async ({ open }) => {
    const person = await signUp('Nia NoScript');
    const organization = await createOrganization(person, 'Import with no script');
    const page = await open(person, { javaScriptEnabled: false });
    await page.goto(dataPage(organization));
    await page.getByText('Take an archive into this organization').click();
    await page.getByLabel(/it cannot take a second/).check();
    await page.getByRole('button', { name: 'Get this organization ready' }).click();
    await expect(page.getByText('Waiting for your operator')).toBeVisible();
  });

  test('sends a box left unticked back with an error, not a change', async ({ open }) => {
    const person = await signUp('Una Unticked');
    const organization = await createOrganization(person, 'Not meant yet');
    const response = await submit(
      dataPage(organization),
      person.jar,
      /Get this organization ready/,
    );
    expect(response.headers.get('location')).toContain('error=INVALID_INPUT');
    const page = await open(person);
    await page.goto(dataPage(organization));
    // The form waits in its closed panel, as before. Opening it shows it is still on offer.
    await page.getByText('Take an archive into this organization').click();
    await expect(page.getByRole('button', { name: 'Get this organization ready' })).toHaveCount(1);
  });
});

test.describe('imported history', () => {
  test('lists work this person can read, and says plainly when none came with it', async ({
    open,
    world,
  }) => {
    const page = await open(world.alice);
    await page.goto(`${dataPage(world.organization)}/work`);
    await expect(page.getByRole('heading', { name: 'Imported history' })).toBeVisible();
    // A piece of work from the page's own list, not the first link of the navigation's lists.
    await page.getByRole('main').getByRole('list').getByRole('link').first().click();
    await expect(page.getByText('No history came with this work.')).toBeVisible();
    await expectNoProblems(page);
  });

  test('reads as missing for a member, and for work that is not here', async ({ open, world }) => {
    const member = await open(world.bob);
    const refused = await member.goto(`${dataPage(world.organization)}/work/${world.work.queued}`);
    expect(refused?.status()).toBe(404);
    const owner = await open(world.alice);
    const absent = await owner.goto(`${dataPage(world.organization)}/work/${world.organization}`);
    expect(absent?.status()).toBe(404);
    const malformed = await owner.goto(`${dataPage(world.organization)}/work/not-an-id`);
    expect(malformed?.status()).toBe(404);
  });
});
